def store_prediction(collection, data, prediction_result):
    """Store the prediction data and result in MongoDB"""
    document = {
        "timestamp": datetime.now(timezone.utc),
        "input_data": data,
        "prediction_result": prediction_result
    }
    try:
        collection.insert_one(document)
        print(f"Stored prediction in database")
    except Exception as e:
        print(f"Error storing in database: {e}")

def analyze_medical_data(data, condition_type):
    
    try:
        if condition_type == "diabetes":
            prompt = f"""Gender: {data.get('gender', 'N/A')} - Age: {data.get('age', 'N/A')} - Hypertension: {data.get('hypertension', 'N/A')} - Heart Disease: {data.get('heartdisease', 'N/A')} - Smoking History: {data.get('smokinghistory', 'N/A')} - BMI: {data.get('bmi', 'N/A')} - HbA1c Level: {data.get('hb1aclevel', 'N/A')} - Blood Glucose Level: {data.get('bloodglucoselevel', 'N/A')}"""
        
        
        elif condition_type == "heart":
            prompt = f"Age: {data.get('age', 'N/A')} - Sex: {data.get('sex', 'N/A')} - Chest Pain Type: {data.get('chestpaintype', 'N/A')} - Resting BP (mm Hg): {data.get('restingbp', 'N/A')} - Cholesterol (mg/dL): {data.get('cholesterol', 'N/A')} - Fasting Blood Sugar: {data.get('fastingbs', 'N/A')} - Resting ECG: {data.get('restingecg', 'N/A')} - Max Heart Rate: {data.get('maxhr', 'N/A')} - Exercise Angina: {data.get('exerciseangina', 'N/A')} - Oldpeak: {data.get('oldpeak', 'N/A')}"

        elif condition_type == "obesity":
            prompt = f"""Gender: {data.get('gender', 'N/A')} - Age: {data.get('age', 'N/A')} - Height: {data.get('height', 'N/A')} - Weight: {data.get('weight', 'N/A')} - Family History: {data.get('family_history_with_overweight', 'N/A')} - Frequent Caloric Food: {data.get('frequent_caloric_food', 'N/A')} - Vegetable Consumption: {data.get('vegetable_consumption', 'N/A')} - Daily Meals: {data.get('daily_meals', 'N/A')} - Eating Between Meals: {data.get('eating_between_meals', 'N/A')} - Smoking: {data.get('smoking', 'N/A')} - Water Consumption: {data.get('daily_water_consumption', 'N/A')} - Physical Activity: {data.get('physical_activity_frequency', 'N/A')} - Technology Use: {data.get('technology_use_time', 'N/A')} - Alcohol Consumption: {data.get('alcohol_consumption', 'N/A')} - Transportation: {data.get('transportation_mode', 'N/A')}"""
        else:
            return {"error": "Invalid condition type"}, 400

        # Get prediction from Gemini
        if condition_type == "diabetes":
            response = chat_session.send_message(prompt)
            result = response.text
            print(result)
        elif condition_type == "heart":
            response = chat_session_2.send_message(prompt)
            result = response.text
            print(result)
        elif condition_type == "obesity":
            response = chat_session_3.send_message(prompt)
            result = response.text
            print(result)

        return {
            "result": result[14:-2]
        }, 200

    except Exception as e:
        print(f"Error in analysis: {e}")
        return {"error": str(e)}, 500

@app.route('/predict/<condition_type>', methods=['POST'])
def predict(condition_type):
    """
    Endpoint for medical condition prediction
    """
    try:
        data = request.json
        print(data)
        if not data:
            return jsonify({"error": "No data provided"}), 400

        result, status_code = analyze_medical_data(data, condition_type)
        if condition_type == "diabetes":
            collection = diabetes_collection
        elif condition_type == 'heart':
            collection = heart_collection
        elif condition_type == 'obesity':
            collection = obesity_collection
        store_prediction(collection, data, result)
        return jsonify(result), status_code

    except Exception as e:
        print(f"Error processing request: {e}")
        return jsonify({"error": str(e)}), 500

@app.route('/health', methods=['GET'])
def health_check():
    """
    Simple health check endpoint
    """
    return jsonify({"status": "healthy", "model": "gemini-1.5-pro"}), 200

if __name__ == '__main__':
    app.run(debug=True, port=5000) 